<template ::key="key" xmlns:el-table="http://www.w3.org/1999/html">
    <div id="admin_comp">
        <el-card style="    margin-bottom: 20px; ">
            <div slot="header">
                <span style="font-size: 26px;">综合查询选项</span>
            </div>
            <div>
                <el-row :gutter="10">
                    <el-form ref="searchFormData" :model="searchFormData" label-width="80px">
                        <el-col :span="4">
                            <el-form-item label="竞赛名称" prop="compName">
                                <el-input v-model="searchFormData.compName"></el-input>
                            </el-form-item>
                        </el-col>
                        <el-col :span="4">
                            <el-form-item label="主办单位" prop="organizer">
                                <el-input v-model="searchFormData.organizer"></el-input>
                            </el-form-item>
                        </el-col>
                        <el-col :span="4">
                            <el-form-item label="竞赛级别" prop="level">
                                <el-select v-model="searchFormData.level" placeholder="请选择竞赛级别">
                                    <el-option label="国家级" value="0"></el-option>
                                    <el-option label="省级" value="1"></el-option>
                                    <el-option label="校级" value="2"></el-option>
                                    <el-option label="全部" value></el-option>
                                </el-select>
                            </el-form-item>
                        </el-col>
                        <el-col :span="4">
                            <el-form-item label="所属类别" prop="subjectType">
                                <el-input v-model="searchFormData.subjectType"></el-input>
                            </el-form-item>
                        </el-col>
                        <el-col :span="4">
                            <el-form-item label="竞赛地点" prop="place">
                                <el-input v-model="searchFormData.place"></el-input>
                            </el-form-item>
                        </el-col>
                        <el-col :span="4">
                            <el-form-item label="竞赛状态" prop="compState">
                                <el-select v-model="searchFormData.compState" placeholder="请选择竞赛状态">
                                    <el-option label="规划中" value=0></el-option>
                                    <el-option label="报名中" value=1></el-option>
                                    <el-option label="备赛中" value=2></el-option>
                                    <el-option label="比赛中" value=3></el-option>
                                    <el-option label="已结束" value=4></el-option>
                                    <el-option label="全部" value></el-option>
                                </el-select>
                            </el-form-item>
                        </el-col>
                    </el-form>
                </el-row>
                <el-row>
                    <el-col :span="3" :offset="21">
                        <el-button
                                type="primary"
                                size="medium"
                                icon="el-icon-search"
                                style="    float: right;border-radius: 20px"
                                @click="moreSearch()"
                        >筛选 / 查询
                        </el-button>
                    </el-col>
                </el-row>
            </div>
        </el-card>

        <!--竞赛详情表头部分-->
        <el-card class="boxc-ard" style="height: 920px">
            <div slot="header" class="clearfix">
                <span>竞赛信息详情</span>
                <div style="float: right;">
                    <el-upload action="uploadAction" style="display: inline-block;" :show-file-list="false" :on-success="successUpload">
                        <el-button
                                type="primary"
                                size="medium"
                                icon="el-icon-upload2"
                                style="margin-left: 10px;border-radius: 20px"
                        >批量导入
                        </el-button>
                    </el-upload>
                    <el-button
                            type="warning"
                            size="medium"
                            icon="el-icon-circle-plus-outline"
                            style="margin-left: 10px;border-radius: 20px"
                            @click="addNewComp()"
                    >单个新增
                    </el-button>
                    <el-popconfirm title="确定删除这些数据吗？" @confirm="delBatch()">
                        <template slot="reference">
                            <el-button type="danger" size="medium" icon="el-icon-remove-outline"
                                       style="margin-left: 10px;border-radius: 20px">批量删除
                            </el-button>
                        </template>
                    </el-popconfirm>
                    <el-button
                            type="success"
                            size="medium"
                            icon="el-icon-download"
                            style="margin-left: 10px;border-radius: 20px"
                            @click="exp()"
                    >导出报表
                    </el-button>
                </div>
            </div>

            <!--竞赛详情表格-->
            <el-table
                    v-loading="loading"
                    :data="tableData.slice((currentPage-1)*pagesize,currentPage*pagesize)"
                    @selection-change="handleSelectionChange"
                    @row-key="getRowKeys"
                    stripe
                    border
                    height="770px"
                    style="width: 100%;"
                    class="elTable"
                    @row-click="getDetails"
                    :default-sort="{prop: 'date', order: 'descending'}"
            >
                <el-table-column type="selection" width="40" align="center" :reserve-selection="true"></el-table-column>
                <!--                <el-table-column align="center" prop="id" label="#" width="50px"></el-table-column>-->
                <el-table-column align="center" prop="compName" label="竞赛名称" sortable>
                    <template slot-scope="scope">
                        <a :href="scope.row.comp_link">{{ scope.row.compName }}</a>
                    </template>
                </el-table-column>
                <el-table-column align="center" prop="organizer" label="主办单位" sortable></el-table-column>
                <el-table-column align="center" prop="level" label="级 别" sortable>
                    <template slot-scope="scope">
                        <p v-if="scope.row.level==0">国家级</p>
                        <p v-if="scope.row.level==1">省级</p>
                        <p v-if="scope.row.level==2">校级</p>
                    </template>
                </el-table-column>
                <el-table-column align="center" prop="subjectType" label="所属类别"></el-table-column>
                <el-table-column align="center" prop="occurrenceTime" label="比赛时间" sortable>
                    <template slot-scope="scope">
                        {{scope.row.occurrenceTime|dataTime}}
                    </template>
                </el-table-column>
                <el-table-column align="center" prop="place" label="比赛地点"></el-table-column>
<!--                <el-table-column align="center" prop="参赛队伍" label="竞赛报名详情">-->
<!--                    <template slot-scope="scope">-->
<!--                        <el-link type="primary" :underline="false" @click="checkProjects(scope.row.id)"><i-->
<!--                                class="el-icon-view el-icon&#45;&#45;right"></i>参赛队伍列表-->
<!--                        </el-link>-->
<!--                        &lt;!&ndash;<el-button size="mini" style="background-color: #009688"  plain @click="checkProjects(scope.row.id)">参赛项目列表</el-button>&ndash;&gt;-->
<!--                    </template>-->
<!--                </el-table-column>-->
                <el-table-column align="center" prop="comp_disctibution" label="竞赛描述"></el-table-column>
                <el-table-column align="center" prop="compState" label="状态" sortable width="80px">
                    <template slot-scope="scope">
                        <el-tag effect="dark"
                                :type="scope.row.compState === 0 ? 'info' :       /*规划中*/
              (scope.row.compState === 1 ? 'primary':       /*可报名*/
              (scope.row.compState === 2 ? 'success':       /*备赛中*/
              (scope.row.compState === 3 ? 'warning':       /*比赛中*/
              'danger')))"
                                disable-transitions
                        >
                            <span v-if="scope.row.compState==0">规划中</span>
                            <span v-if="scope.row.compState==1">报名中</span>
                            <span v-if="scope.row.compState==2">备赛中</span>
                            <span v-if="scope.row.compState==3">比赛中</span>
                            <span v-if="scope.row.compState==4">已结束</span>
                        </el-tag>
                    </template>
                </el-table-column>
                <el-table-column align="center" label="操作" width="180px">
                    <template slot-scope="scope">
                        <div class="operation-buttons">
                            <el-tag type="info">
                                <el-tooltip class="item" effect="dark" content="编辑" placement="top">
                                    <el-link icon="el-icon-edit" @click="dialogFormVisible=true" class="edit-button">
                                        编辑
                                    </el-link>
                                </el-tooltip>
                            </el-tag>
                            <!-- 添加删除按钮 -->
                            <el-tag>
                                <el-tooltip class="item" effect="dark" content="删除" placement="top">
                                    <el-link icon="el-icon-delete" @click="deleteItem(scope.row.id)"
                                             class="delete-button">
                                        删除
                                    </el-link>
                                </el-tooltip>
                            </el-tag>
                        </div>
                    </template>
                </el-table-column>
            </el-table>
            <div id="fenye">
                <!-- 设置layout，表示需要显示的内容，用逗号分隔，布局元素会依次显示。
                  prev表示上一页，next为下一页，pager表示页码列表，
                  除此以外还提供了jumper和total，size和特殊的布局符号->，->后的元素会靠右显示，
                  jumper表示跳页元素，
                  total表示总条目数，
                  page-size  每页多少条数据
                  @current-change="current_change" //currentPage改变时会触发
                size用于设置每页显示的页码数量。-->
                <el-pagination
                        background
                        layout="prev, pager, next"
                        :total="tableData.length"
                        :page-size="11"
                        @current-change="current_change"
                        :current-page.sync="currentPage"
                ></el-pagination>
            </div>
        </el-card>
        <!-- 竞赛项目展示模态框 -->
        <el-dialog title="参赛队伍列表" :visible.sync="projectVisible">
            <el-table :data="projectData" stripe border style="width: 100%" max-height="500">
                <el-table-column align="center" prop="id" label="队伍编号" width="80px"></el-table-column>
                <el-table-column align="center" prop="projectName" label="队伍名称"></el-table-column>
                <el-table-column align="center" prop="createByTeacher.college.nickname" label="所属学院"></el-table-column>
                <el-table-column align="center" prop="createByTeacher.nickname" label="指导老师"
                                 width="120px"></el-table-column>
                <el-table-column align="center" prop="pay" label="参赛学生"></el-table-column>
<!--                <el-table-column align="center" prop="pay" label="预算"></el-table-column>-->
                <el-table-column align="center" prop="applyState" label="状态">
                    <template slot-scope="scope">
                        <el-tag
                                :type="scope.row.applyState === 1 ? 'success' : 'warning'"
                                disable-transitions
                        >{{scope.row.applyState==1?'已审核':'未审核'}}
                        </el-tag>
                    </template>
                </el-table-column>
            </el-table>
        </el-dialog>
        <!-- 修改信息模态框 -->
        <el-dialog title="修改比赛信息" :span="8" :visible.sync="dialogFormVisible" :before-close="handleClose">
            <el-form label-position="right" label-width="150px" :model="rowData" ref="form" :rules="rules">
                <el-form-item label="竞赛名称" prop="compName">
                    <el-input v-model="rowData.compName" autocomplete="off"></el-input>
                </el-form-item>
                <el-form-item label="主办单位" prop="organizer">
                    <el-input v-model="rowData.organizer" autocomplete="off"></el-input>
                </el-form-item>
                <el-form-item label="竞赛地点" prop="place">
                    <el-input v-model="rowData.place" autocomplete="off"></el-input>
                </el-form-item>
                <el-form-item label="所属类别" prop="subjectType">
                    <el-input v-model="rowData.subjectType" autocomplete="off"></el-input>
                </el-form-item>
                <el-form-item label="最多项目参与数" prop="maxCountProject">
                    <el-input v-model="rowData.maxCountProject" autocomplete="off"></el-input>
                </el-form-item>
                <el-form-item label="项目最多参与老师数" prop="maxCountTeacher">
                    <el-input v-model="rowData.maxCountTeacher" autocomplete="off"></el-input>
                </el-form-item>
                <el-form-item label="项目最多参与学生数" prop="maxCountStudent">
                    <el-input v-model="rowData.maxCountStudent" autocomplete="off"></el-input>
                </el-form-item>
                <el-form-item label="比赛时间">
                    <el-date-picker
                            v-model="rowData.occurrenceTime"
                            type="date"
                            placeholder="选择日期"
                            value-format="yyyy-MM-dd"
                            format="yyyy 年 MM 月 dd 日"
                            :picker-options="occurrenceTimeRule"
                    ></el-date-picker>
                </el-form-item>
                <el-form-item label="可申请时间">
                    <el-date-picker
                            v-model="rowData.canApplyTime"
                            type="date"
                            placeholder="选择日期"
                            value-format="yyyy-MM-dd"
                            format="yyyy 年 MM 月 dd 日"
                            :picker-options="canApplyTimeRule"
                    ></el-date-picker>
                </el-form-item>
                <el-form-item label="截止参加时间">
                    <el-date-picker
                            v-model="rowData.notApplyTime"
                            type="date"
                            placeholder="选择日期"
                            value-format="yyyy-MM-dd"
                            format="yyyy 年 MM 月 dd 日"
                            :picker-options="notApplyTimeRule"
                    ></el-date-picker>
                </el-form-item>
                <el-form-item label="竞赛级别">
                    <el-select v-model="rowData.level" placeholder>
                        <el-option label="国家级" :value="0"></el-option>
                        <el-option label="省级" :value="1"></el-option>
                        <el-option label="校级" :value="2"></el-option>
                    </el-select>
                </el-form-item>
                <el-form-item label="竞赛状态">
                    <el-select v-model="rowData.compState" placeholder>
                        <el-option label="规划中" :value="0"></el-option>
                        <el-option label="报名中" :value="1"></el-option>
                        <el-option label="备赛中" :value="2"></el-option>
                        <el-option label="比赛中" :value="3"></el-option>
                        <el-option label="已结束" :value="4"></el-option>
                    </el-select>
                </el-form-item>
            </el-form>
            <div slot="footer" class="dialog-footer">
                <el-button @click="dialogFormVisible = false">取 消</el-button>
                <el-button type="primary" @click="editComp()">确定修改</el-button>
            </div>
        </el-dialog>
    </div>
</template>
<style>
    .clearfix {
        font-size: 26px;
    }

    #fenye {
        text-align: center;
        margin-top: 20px;
    }

    .operation-buttons {
        display: flex;
        justify-content: center;
    }

    .edit-button {
        color: #409EFF; /* 编辑按钮颜色 */
    }

    .delete-button {
        color: #F56C6C; /* 删除按钮颜色 */
    }

    .operation-buttons .el-tooltip.item {
        margin: 0 10px;
    }
</style>
<script>
    import api from '../../main.js'
    import dayjs from 'dayjs'

    export default {
        inject: ['reload'],
        name: "admin_comp",
        data() {
            return {
                loading: true,
                pagesize: 11,
                currentPage: 1,
                dialogFormVisible: false,
                projectVisible: false,
                projectData: [],
                rowIndex: -1,
                rowData: {},
                tableData: [],
                multipleSelection: [],
                uploadAction:api+'/comp/upload',
                searchFormData: {
                    compName: "",
                    organizer: "",
                    level: "",
                    subjectType: "",
                    place: "",
                    compState: ""
                },
                rules: {
                    compName: [
                        {required: true, message: "请输入竞赛名称", trigger: "blur"}
                    ],
                    organizer: [
                        {required: true, message: "请输入主办单位", trigger: "blur"}
                    ],
                    place: [
                        {required: true, message: "请输入竞赛地点", trigger: "blur"}
                    ],
                    subjectType: [
                        {required: true, message: "请输入所属类别", trigger: "blur"}
                    ],
                    occurrenceTime: [
                        {required: true, message: "请输选择竞赛时间", trigger: "blur"}
                    ],
                    level: [
                        {required: true, message: "请输选择竞赛级别", trigger: "blur"}
                    ],
                    maxCountProject: [
                        {required: true, message: '项目最大数不能为空，未要求可填写成999', trigger: "blur"},
                        {type: 'number', message: '项目最大数必须为数字值', trigger: "blur"}
                    ],
                    maxCountTeacher: [
                        {required: true, message: '项目中老师最大数不能为空，未要求可填写成999', trigger: "blur"},
                        {type: 'number', message: '项目中老师最大数必须为数字值', trigger: "blur"}
                    ],
                    maxCountStudent: [
                        {required: true, message: '项目中学生最大数不能为空，未要求可填写成999', trigger: "blur"},
                        {type: 'number', message: '项目中老师最大数必须为数字值', trigger: "blur"}
                    ]
                },
                occurrenceTimeRule: {
                    disabledDate: time => {
                        // 禁用今天之前的日期
                        return time.getTime() < Date.now();
                    }
                },
                canApplyTimeRule: {
                    disabledDate: time => {
                        // 禁用今天之前或发生时间之前的日期
                        if (this.rowData.occurrenceTime) {
                            return (new Date(this.rowData.occurrenceTime).getTime() - 24 * 3600 * 1000 < time.getTime() || time.getTime() < Date.now());
                        }
                    }
                },
                notApplyTimeRule: {
                    disabledDate: time => {
                        // 禁用今天之前或发生时间之前的日期
                        if (this.rowData.occurrenceTime) {
                            return (new Date(this.rowData.occurrenceTime).getTime() - 24 * 3600 * 1000 < time.getTime() || time.getTime() < Date.now());
                        }
                    }
                }
            };
        },

        /*页面加载的时候做一些事情，在created里面*/
        created() {
            this.getDetails();
            this.moreSearch();
        },

        mounted() {
            var that = this;
            that.loading = true;
            this.$axios
                .post(api + "/comp/getAllComps")
                .then(function (response) {
                    // 确保请求成功后再设置数据
                    that.tableData = response.data;
                    that.loading = false;
                })
                .catch(function (error) {
                    // 处理请求失败的情况
                    that.loading = false;
                    that.$message.error("获取竞赛详情列表信息失败，请稍后再试！");
                });
        },

        methods: {
            /**
             * 模糊查询
             */
            moreSearch() {
                let that = this;
                let searchData = new FormData();
                searchData.append("compName", that.searchFormData.compName);
                searchData.append("organizer", that.searchFormData.organizer);
                searchData.append("level", that.searchFormData.level);
                searchData.append("subjectType", that.searchFormData.subjectType);
                searchData.append("place", that.searchFormData.place);
                searchData.append("compState", that.searchFormData.compState);
                this.$axios
                    .post(api + "/comp/moreSearch", searchData)
                    .then(function (response) {
                        /*将查询得到的数据存储在tableData变量中*/
                        that.tableData = response.data;
                    })
                    .catch(function (error) {
                        that.$message.error("系统错误，操作失败，请稍后再试!");
                    });
                /**
                 * 清空搜索栏
                 */
                this.searchFormData = {
                    compName: '',
                    organizer: '',
                    level: '',
                    subjectType: '',
                    place: '',
                    compState: ''
                }
            },
            /**
             * 查看项目详情
             * @param row
             */
            getDetails(row) {
                // this.rowData = row;
                this.rowData = JSON.parse(JSON.stringify(row)); // 先转换为字符串，然后再转换
                if (row) {
                    // 处理日期格式
                    row.occurrenceTime = dayjs(row.occurrenceTime).format("YYYY-MM-DD");
                    row.canApplyTime = dayjs(row.canApplyTime).format("YYYY-MM-DD");
                    row.notApplyTime = dayjs(row.notApplyTime).format("YYYY-MM-DD");
                    this.rowData = row;
                } else {
                    this.rowData = {};
                }
            },
            /**
             * 修改比赛信息
             * @param index
             */
            editComp() {
                let that = this;
                let comp = new FormData();
                comp.append("id", that.rowData.id);
                comp.append("compName", that.rowData.compName);
                comp.append("organizer", that.rowData.organizer);
                comp.append("level", that.rowData.level);
                comp.append("subjectType", that.rowData.subjectType);
                comp.append("occurrenceTime", that.rowData.occurrenceTime);
                comp.append("canApplyTime", that.rowData.canApplyTime);
                comp.append("notApplyTime", that.rowData.notApplyTime);
                comp.append("maxCountTeacher", that.rowData.maxCountTeacher);
                comp.append("maxCountProject", that.rowData.maxCountProject);
                comp.append("place", that.rowData.place);
                comp.append("compState", that.rowData.compState);
                this.$confirm("确认修改？")
                    .then(_ => {
                        this.$axios
                            .post(api + "/comp/addComp", comp)
                            .then(function (response) {
                                that.$set(that.tableData, that.rowData.id - 1, that.rowData);

                                //提示信息
                                that.$message({
                                    message: "修改成功！",
                                    type: "success"
                                });
                                //模态框关闭
                                that.dialogFormVisible = false;
                                that.reload();
                            })
                            .catch(function (error) {
                                that.$message.error(error);
                            });

                        done();
                    })
                    .catch(_ => {
                    });

            },
            /**
             *
             * @param compId
             */
            checkProjects(compId) {
                let that = this;
                that.projectVisible = true;
                this.$axios
                    .get(
                        api + `/comp/getProjectLists/` + compId
                    )
                    .then(function (response) {
                        that.projectData = response.data;
                    })
                    .catch(function (error) {
                    });
            },
            /**
             * 增加新竞赛  跳转页面
             */
            addNewComp() {
                this.$router.push(`/admin/comp/add`);
            },
            current_change(currentPage) {
                //改变当前页
                this.currentPage = currentPage;
            },
            handleClose(done) {
                this.$confirm("确认关闭？")
                    .then(_ => {
                        done();
                    })
                    .catch(_ => {
                    });
            },
            /*导出报表的方法实现*/
            exp() {
                location.href = 'http://localhost:8080/comp/export'
            },
            delBatch() {
                if (this.multipleSelection.length === 0) {
                    this.$message.warning("请勾选您要删除的项")
                }
                // request.put("comp/delBatch",this.multipleSelection)
                // 打印数据查询一下格式
                console.log(this.multipleSelection)
                this.$axios
                    .post(api + "/comp/delBatch", this.multipleSelection)
                    .then(response => {
                        const res = response.data;
                        if (res.code === '0') {
                            this.$message({
                                message: "批量删除成功",
                                type: 'success'
                            });
                            this.moreSearch();
                        }
                        // 清空当前用户选择的最新状态
                        this.multipleSelection = [];
                    })
                    .catch(error => {
                        console.error("批量删除请求失败:", error);
                        this.$message.error("批量删除请求失败，请稍后重试");
                    });
            },
            handleSelectionChange(val) {
                //记录当前用户选择的最新状态
                this.multipleSelection = val;
            },
            deleteItem(id) {
                // 删除按钮点击事件处理方法
                this.$confirm('确定删除该竞赛信息吗？')
                    .then(_ => {
                        // 向后端发送删除请求
                        this.$axios
                            .delete(api + '/comp/deleteComp/' + id) // 将 ID 作为路径参数传递
                            .then(response => {
                                const res = response.data;
                                if (res.code === '0') {
                                    this.$message({
                                        message: "删除成功",
                                        type: 'success'
                                    });
                                    this.moreSearch();
                                } else {
                                    this.$message({
                                        message: res.msg,
                                        type: 'error'
                                    });
                                }
                            })
                            .catch(error => {
                                this.$message.error('删除失败，请稍后重试');
                            });
                    })
                    .catch(_ => {
                        // 用户取消删除操作
                    });
            },
            getRowKeys(row) {
                return row.id;
            },
            successUpload(res){
                if (res.code === '0') {
                    this.$message({
                        message: "批量导入成功",
                        type: 'success'
                    });
                }else {
                    this.$message.error("批量导入失败")
                }
            }
        },
        computed: {},
        filters: {
            dataTime: function (value) {
                if (value == undefined)
                    return '-';
                value = new Date(value)
                if (value instanceof Date) {
                    var d = value;
                    var year = d.getFullYear();
                    var m = d.getMonth() + 1;
                    var day = d.getDate() < 10 ? '0' + d.getDate() : d.getDate();
                    var myDate = year + '年' + m + '月 ' + day + '日';
                    return myDate;
                } else {
                    return "-";
                }
            }
        }
    };
</script>